import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

export async function GET(request: Request) {
  try {
    // 1. Lấy các tham số lọc từ URL
    const { searchParams } = new URL(request.url);
    const city = searchParams.get('city');
    const district = searchParams.get('district');
    const min_price = searchParams.get('min_price');
    const max_price = searchParams.get('max_price');
    const min_area = searchParams.get('min_area');
    const max_area = searchParams.get('max_area');

    // 2. Đọc toàn bộ dữ liệu từ data.json
    const filePath = path.join(process.cwd(), 'src', 'app', 'api', 'data', 'data.json');
    const fileContents = fs.readFileSync(filePath, 'utf8');
    let posts = JSON.parse(fileContents);

    // 3. Tiến hành lọc dữ liệu theo từng điều kiện (Nếu có)
    if (city) {
      posts = posts.filter((p: any) => String(p.city) === String(city));
    }
    if (district) {
      posts = posts.filter((p: any) => String(p.district) === String(district));
    }
    if (min_price) {
      posts = posts.filter((p: any) => p.price >= Number(min_price));
    }
    if (max_price) {
      posts = posts.filter((p: any) => p.price <= Number(max_price));
    }
    if (min_area) {
      posts = posts.filter((p: any) => p.area >= Number(min_area));
    }
    if (max_area) {
      posts = posts.filter((p: any) => p.area <= Number(max_area));
    }

    // 4. Trả về danh sách bài viết đã được lọc
    return NextResponse.json(posts);
    
  } catch (error) {
    console.error("Lỗi đọc file bài viết:", error);
    return NextResponse.json(
      { error: 'Không thể tải dữ liệu Bài viết' }, 
      { status: 500 }
    );
  }
}